                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        rr,cc=r+dr,q+dc
                        if 0<=rr<H and 0<=cc<W and a[rr,cc]!=bg and not seen[rr,cc]:
                            seen[rr,cc]=True; stack.append((rr,cc))
                out.append(cells)
    return out

def normP(cells):
