def shapekey(cells):
    r0=min(p[0] for p in cells); c0=min(p[1] for p in cells)
    return tuple(sorted((r-r0,c-c0) for r,c in cells))
def f(g):
    a=np.array(g)
    bg=Counter(a.flatten()).most_common(1)[0][0]
    cs=comps_of(a,bg)
    cnt=Counter(x['col'] for x in cs)
    singles=[c for c,v in cnt.items() if v==1]
    tgt=singles[0] if len(singles)==1 else None
    res=defaultdict(list)
    for x in cs: res[shapekey(x['cells'])].append(x)
    ch=None
    # Branch A: exactly two same-shape comps with different colors -> recolor minority color comp to the singleton color
    for vv in list(res.values()):
        if len(vv)>=2:
            cols=[x['col'] for x in vv]
            ncols=list(set(cols))
            if len(ncols)>1 and len(vv)==2 and (tgt is None or True):
                sel=[x for x in vv if cnt[x['col']]==1]
                if sel:
                    ch=sel[0]; break
    if ch is None and len(singles)==1:
        # single comp per shape but diffcolors across group
        for vv in list(res.values()):
            if len(vv)>=2 and set(x['col'] for x in vv)!= {list(set(x['col'] for x in vv))[0]}:
                # pick comp whose color count==1 (singleton color)
                sel=[x for x in vv if cnt[x['col']]==1]
                if sel: ch=sel[0]; break
    if ch is None and tgt is not None:
        def distA(ccs,p): return min(abs(r-p[0])+abs(c-p[1]) for r,c in ccs)
        d=tuple(d)
        best=None;bestval=-1
        for sk,vv in res.items():
            if len(vv)<2: continue
            for x in vv:
                val=max(distA(y['cells'],d) for y in vv if y is not x)
                if val>bestval: bestval=val; best=x
        ch=best
    if ch is None: return a.tolist()
    out=a.copy()
    for r,c in ch['cells']: out[r,c]=tgt
    return out.tolist()

